namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string Department { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string DepartmentCode { get; set; } = string.Empty;
    public string Schedule { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public int InstructorId { get; set; }
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required]
    public string StudentName { get; set; } = string.Empty;

    [Required]
    public string StudentId { get; set; } = string.Empty;

    [Required]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    IReadOnlyList<Department> GetDepartments();
    Department? GetDepartment(string code);
    IReadOnlyList<Course> GetCourses(string? searchTerm = null, string? departmentCode = null);
    Course? GetCourse(int id);
    IReadOnlyList<Course> GetFeaturedCourses();
    Instructor? GetInstructor(int id);
    bool SubmitEnrollmentRequest(EnrollmentRequest request);
}

public class CatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Code = "ENG", Name = "English", Description = "Study of literature, writing, and critical analysis." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor", Bio = "Expert in algorithms and machine learning with 15 years of teaching experience.", Email = "achen@university.edu", Department = "CS" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor", Bio = "Specializes in applied mathematics and numerical analysis.", Email = "rmartinez@university.edu", Department = "MATH" },
            new() { Id = 3, Name = "Dr. Sarah Thompson", Title = "Professor", Bio = "Research focus on quantum mechanics and particle physics.", Email = "sthompson@university.edu", Department = "PHYS" }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Title = "Introduction to Programming", Code = "CS 101", Description = "Learn the fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures.", Credits = 3, DepartmentCode = "CS", Schedule = "MWF 9:00-9:50 AM", Location = "Tech Hall 101", InstructorId = 1, IsFeatured = true },
            new() { Id = 2, Title = "Data Structures", Code = "CS 201", Description = "Study of fundamental data structures including arrays, linked lists, trees, graphs, and hash tables.", Credits = 4, DepartmentCode = "CS", Schedule = "TTh 10:30-11:45 AM", Location = "Tech Hall 205", InstructorId = 1, IsFeatured = true },
            new() { Id = 3, Title = "Algorithms", Code = "CS 301", Description = "Design and analysis of algorithms. Covers sorting, searching, dynamic programming, and graph algorithms.", Credits = 4, DepartmentCode = "CS", Schedule = "MWF 1:00-1:50 PM", Location = "Tech Hall 301", InstructorId = 1, IsFeatured = false },
            new() { Id = 4, Title = "Calculus I", Code = "MATH 101", Description = "Introduction to differential calculus including limits, derivatives, and applications.", Credits = 4, DepartmentCode = "MATH", Schedule = "MWF 8:00-8:50 AM", Location = "Science Building 110", InstructorId = 2, IsFeatured = true },
            new() { Id = 5, Title = "Calculus II", Code = "MATH 102", Description = "Continuation of Calculus I covering integral calculus, sequences, and series.", Credits = 4, DepartmentCode = "MATH", Schedule = "MWF 10:00-10:50 AM", Location = "Science Building 110", InstructorId = 2, IsFeatured = false },
            new() { Id = 6, Title = "Linear Algebra", Code = "MATH 201", Description = "Study of vector spaces, linear transformations, matrices, and eigenvalues.", Credits = 3, DepartmentCode = "MATH", Schedule = "TTh 2:00-3:15 PM", Location = "Science Building 215", InstructorId = 2, IsFeatured = false },
            new() { Id = 7, Title = "General Physics I", Code = "PHYS 101", Description = "Introduction to mechanics, thermodynamics, and waves.", Credits = 4, DepartmentCode = "PHYS", Schedule = "MWF 11:00-11:50 AM", Location = "Physics Lab 100", InstructorId = 3, IsFeatured = true },
            new() { Id = 8, Title = "General Physics II", Code = "PHYS 102", Description = "Electricity, magnetism, optics, and modern physics.", Credits = 4, DepartmentCode = "PHYS", Schedule = "MWF 2:00-2:50 PM", Location = "Physics Lab 100", InstructorId = 3, IsFeatured = false },
            new() { Id = 9, Title = "Quantum Mechanics", Code = "PHYS 301", Description = "Introduction to quantum theory, wave functions, and the Schrödinger equation.", Credits = 3, DepartmentCode = "PHYS", Schedule = "TTh 9:00-10:15 AM", Location = "Physics Lab 300", InstructorId = 3, IsFeatured = false },
            new() { Id = 10, Title = "English Composition", Code = "ENG 101", Description = "Develop effective writing skills through essays, research papers, and critical analysis.", Credits = 3, DepartmentCode = "ENG", Schedule = "MWF 9:00-9:50 AM", Location = "Humanities 105", InstructorId = 1, IsFeatured = false },
            new() { Id = 11, Title = "American Literature", Code = "ENG 201", Description = "Survey of American literature from the colonial period to the present.", Credits = 3, DepartmentCode = "ENG", Schedule = "TTh 1:00-2:15 PM", Location = "Humanities 210", InstructorId = 1, IsFeatured = true }
        };
    }

    public IReadOnlyList<Department> GetDepartments() => _departments.AsReadOnly();

    public Department? GetDepartment(string code) =>
        _departments.FirstOrDefault(d => d.Code.Equals(code, StringComparison.OrdinalIgnoreCase));

    public IReadOnlyList<Course> GetCourses(string? searchTerm = null, string? departmentCode = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentCode))
            query = query.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase));

        if (!string.IsNullOrWhiteSpace(searchTerm))
            query = query.Where(c =>
                c.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));

        return query.ToList().AsReadOnly();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList().AsReadOnly();

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public bool SubmitEnrollmentRequest(EnrollmentRequest request) => true;
}

