@page "/courses"
@inject ICatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="/courses" class="mb-4">
    <div class="row g-3 align-items-end">
        <div class="col-md-5">
            <label for="searchTerm" class="form-label">Search</label>
            <input type="text" class="form-control" id="searchTerm" name="SearchTerm" value="@SearchTerm" placeholder="Search courses..." />
        </div>
        <div class="col-md-4">
            <label for="departmentCode" class="form-label">Department</label>
            <select class="form-select" id="departmentCode" name="DepartmentCode">
                <option value="">All Departments</option>
                @foreach (var dept in departments)
                {
                    <option value="@dept.Code" selected="@(dept.Code == DepartmentCode)">@dept.Name</option>
                }
            </select>
        </div>
        <div class="col-md-3">
            <button type="submit" class="btn btn-primary w-100">Filter</button>
        </div>
    </div>
</form>

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses found.</div>
}
else
{
    <table class="table table-striped course-table">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Credits</th>
                <th>Department</th>
                <th>Schedule</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                <tr>
                    <td>@course.Code</td>
                    <td>@course.Title</td>
                    <td>@course.Credits</td>
                    <td>@course.DepartmentCode</td>
                    <td>@course.Schedule</td>
                    <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery]
    public string? SearchTerm { get; set; }

    [SupplyParameterFromQuery]
    public string? DepartmentCode { get; set; }

    private IReadOnlyList<Course> courses = [];
    private IReadOnlyList<Department> departments = [];

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        courses = CatalogService.GetCourses(SearchTerm, DepartmentCode);
    }
}

@page "/courses/{Id:int}"
@inject ICatalogService CatalogService

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course could not be found.</p>
    <a href="/courses" class="btn btn-primary">Back to Course List</a>
}
else
{
    <PageTitle>@course.Title</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
            <li class="breadcrumb-item active">@course.Code</li>
        </ol>
    </nav>

    <h1>@course.Title</h1>
    <span class="badge bg-secondary mb-3">@course.Code</span>

    <div class="row mt-3">
        <div class="col-md-8">
            <h4>Description</h4>
            <p>@course.Description</p>

            <div class="row mb-3">
                <div class="col-sm-6">
                    <strong>Credits:</strong> @course.Credits
                </div>
                <div class="col-sm-6">
                    <strong>Department:</strong> @course.DepartmentCode
                </div>
            </div>
            <div class="row mb-3">
                <div class="col-sm-6">
                    <strong>Schedule:</strong> @course.Schedule
                </div>
                <div class="col-sm-6">
                    <strong>Location:</strong> @course.Location
                </div>
            </div>

            <a href="/enroll?CourseId=@course.Id" class="btn btn-success">Enroll in This Course</a>
        </div>

        @if (instructor is not null)
        {
            <div class="col-md-4">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">Instructor</h5>
                        <h6>@instructor.Name</h6>
                        <p class="text-muted">@instructor.Title</p>
                        <p>@instructor.Bio</p>
                        <p><strong>Email:</strong> <a href="mailto:@instructor.Email">@instructor.Email</a></p>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;
    private Instructor? instructor;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
        if (course is not null)
        {
            instructor = CatalogService.GetInstructor(course.InstructorId);
        }
    }
}

@page "/enroll"
@inject ICatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Enrollment Request Submitted!</h4>
        <p>Thank you, <strong>@EnrollmentModel!.StudentName</strong>. Your enrollment request has been received.</p>
        <a href="/courses" class="btn btn-primary">Back to Courses</a>
    </div>
}
else
{
    <EditForm Model="EnrollmentModel" method="post" FormName="enrollment" OnValidSubmit="HandleSubmit">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="studentName" class="form-label">Student Name</label>
            <InputText id="studentName" class="form-control" @bind-Value="EnrollmentModel!.StudentName" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" class="form-control" @bind-Value="EnrollmentModel!.StudentId" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" class="form-select" @bind-Value="EnrollmentModel!.CourseId">
                <option value="0">-- Select a course --</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id">@course.Code - @course.Title</option>
                }
            </InputSelect>
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment</button>
    </EditForm>
}

@code {
    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    [SupplyParameterFromForm]
    public EnrollmentRequest? EnrollmentModel { get; set; }

    private IReadOnlyList<Course> courses = [];
    private bool submitted;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses();
        EnrollmentModel ??= new EnrollmentRequest
        {
            CourseId = CourseId ?? 0
        };
    }

    private void HandleSubmit()
    {
        CatalogService.SubmitEnrollmentRequest(EnrollmentModel!);
        submitted = true;
    }
}

